        $file = DB::transaction(fn () => StrapiUpload::update($file, $this->infos($request)[0] ?? [], $upload));

        return response()->json(StrapiUpload::wire($file));
    }

    /**
     * What populate=related (or *) adds to each file: every entry linked to it, once per link and
     * in link order, each with its Strapi uid as __type; Strapi leaves out the entries of types the
     * caller may not read. One query per linked type, whatever the number of files.
     *
     * @param \Illuminate\Support\Collection<int, File> $files
     * @return \Closure(File): array
     */
    private function related(Request $request, \Illuminate\Support\Collection $files): \Closure
    {
        $populate = $request->query('populate');
        $asked = $populate === '*' || $populate === 'related'
            || (is_string($populate) && in_array('related', array_map('trim', explode(',', $populate)), true))
            || (is_array($populate) && (in_array('related', $populate, true) || ! in_array($populate['related'] ?? false, [false, 'false'], true)));
        if (! $asked) {
            return fn (File $file): array => [];
        }
        $links = DB::table('files_related_mph')->whereIn('file_id', $files->map->getKey()->all())->orderBy('id')->get();
        $entries = [];
        foreach (self::TARGETS as $uid => [$modelClass, $serializer]) {
            $ids = $links->where('related_type', (new $modelClass())->getMorphClass())->pluck('related_id')->unique()->values()->all();
            if ($ids === [] || ! StrapiQuery::readable(['model' => $modelClass], $request->user())) {
                continue;
            }
            $query = $modelClass::query()->whereKey($ids);
            StrapiQuery::scope($query, $request->user());
            $rows = $query->get()->filter(fn ($row) => StrapiQuery::visible($row, $request->user()))->values();
            foreach (StrapiPopulate::many($rows, [], $serializer, $request->user()) as $i => $wire) {
                $entries[$rows[$i]->getMorphClass()][$rows[$i]->getKey()] = $wire + ['__type' => $uid];
            }
        }
        $byFile = [];
        foreach ($links as $link) {
            $entry = $entries[$link->related_type][$link->related_id] ?? null;
            if ($entry !== null) {
                $byFile[$link->file_id][] = $entry;
            }
        }

        return fn (File $file): array => ['related' => $byFile[$file->getKey()] ?? []];
    }

    private function files(Request $request): Builder
    {
        return File::query()->forUser($request->user());
    }

    private function file(Request $request, string $id, string $missing): File
    {
        $file = ctype_digit($id) ? $this->files($request)->find((int) $id) : null;
        if ($file === null || ! Gate::allows('view', $file)) {
            throw new StrapiError(404, 'NotFoundError', $missing);
        }

        return $file;
    }

    /** @return list<UploadedFile> the request's `files` (or `files[]`), in order */
    private function uploads(Request $request): array
    {
        $files = $request->file('files');
        $files = $files instanceof UploadedFile ? [$files] : (is_array($files) ? $files : []);

        return array_values(array_filter($files, fn (mixed $f): bool => $f instanceof UploadedFile));
    }

    /** @return list<array> each file's fileInfo, sent as JSON text or as form fields */
    private function infos(Request $request): array
    {
        $info = $request->input('fileInfo');
        if ($info === null) {
            return [];
        }
        $infos = is_array($info) && array_is_list($info) ? $info : [$info];

        return array_map(function (mixed $one): array {
            $decoded = is_string($one) ? json_decode($one, true) : $one;
            if (! is_array($decoded)) {
                throw StrapiError::validation('fileInfo must be an object');
            }

            return $decoded;
        }, $infos);
    }

    /** The entry and media field an upload's ref, refId and field name, or null without them. */
    private function entry(Request $request): ?array
    {
        $ref = $request->input('ref');
        if ($ref === null) {
            return null;
        }
        [$modelClass, $serializer] = self::TARGETS[$ref] ?? [null, null];
        $field = (string) $request->input('field');
        $relation = $serializer === null ? null : ($serializer::FIELDS[$field] ?? null);
        if ($relation === null || ! in_array($relation['kind'] ?? null, ['mediaOne', 'mediaMany'], true)) {
            throw StrapiError::validation("Invalid ref, refId or field: {$ref}.{$field}");
        }
        $query = $modelClass::query();
        $query->forUser($request->user());
        $row = $query->find($request->input('refId'));
        if ($row === null || ! Gate::allows('view', $row)) {
            throw new StrapiError(404, 'NotFoundError', 'Entity not found');
        }
        $this->authorize('update', $row);

        return ['row' => $row, 'relation' => $relation];
    }
